package com.certmanage.server;
import org.junit.jupiter.api.Test;import org.junit.jupiter.api.io.TempDir;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import java.util.*;import java.nio.file.*;import com.fasterxml.jackson.databind.ObjectMapper;import org.apache.sshd.server.SshServer;import org.apache.sshd.server.keyprovider.SimpleGeneratorHostKeyProvider;import org.apache.sshd.common.file.virtualfs.VirtualFileSystemFactory;import org.apache.sshd.sftp.server.SftpSubsystemFactory;import org.apache.sshd.common.config.keys.KeyUtils;
class SftpTransportTest {
 @TempDir Path folder;
 @Test void passwordAndKeyUploadWithoutFingerprint()throws Exception{var target=SshServer.setUpDefaultServer();target.setPort(0);var provider=new SimpleGeneratorHostKeyProvider(folder.resolve("hostkey"));target.setKeyPairProvider(provider);target.setPasswordAuthenticator((u,p,s)->u.equals("user")&&p.equals("secret"));target.setSubsystemFactories(List.of(new SftpSubsystemFactory.Builder().build()));Path remote=Files.createDirectory(folder.resolve("remote"));target.setFileSystemFactory(new VirtualFileSystemFactory(remote));target.start();try{var config=new HashMap<String,Object>(Map.of("type","SFTP","host","127.0.0.1","port",target.getPort(),"username","user","password","secret","connectTimeout",2,"readTimeout",2));ServerService.validate(config);assertFalse(config.containsKey("fingerprint"));var servers=mock(ServerService.class);when(servers.enabled(1)).thenReturn(true);when(servers.snapshot(1)).thenReturn(Map.of("configId",1L));when(servers.connection(1)).thenReturn(config);var transport=new RemoteTransport(servers,new ObjectMapper());config.put("password","wrong-password-secret");var denied=transport.test(1);assertEquals(false,denied.get("success"));assertEquals("AUTHENTICATION_FAILED",denied.get("errorCode"));assertTrue(denied.get("message").toString().contains("密码认证失败"));assertFalse(denied.toString().contains("wrong-password-secret"));config.put("password","secret");transport.execute(1,1,Map.of("remoteDirectory","/"),new byte[]{1},"file.bin");assertArrayEquals(new byte[]{1},Files.readAllBytes(remote.resolve("file.bin")));assertThrows(IllegalArgumentException.class,()->transport.execute(1,1,Map.of("remoteDirectory","/"),new byte[]{2},"file.bin"));assertArrayEquals(new byte[]{1},Files.readAllBytes(remote.resolve("file.bin")));transport.execute(1,1,Map.of("remoteDirectory","/","overwrite",true),new byte[]{2},"file.bin");assertArrayEquals(new byte[]{2},Files.readAllBytes(remote.resolve("file.bin")));var generator=java.security.KeyPairGenerator.getInstance("RSA");generator.initialize(2048);var identity=generator.generateKeyPair();target.setPublickeyAuthenticator((u,k,session)->u.equals("user")&&k.equals(identity.getPublic()));var text=new java.io.StringWriter();try(var writer=new org.bouncycastle.openssl.jcajce.JcaPEMWriter(text)){writer.writeObject(identity.getPrivate());}config.put("authType","KEY");config.remove("password");config.put("privateKey",text.toString());transport.execute(1,1,Map.of("remoteDirectory","/"),new byte[]{3},"key.bin");assertArrayEquals(new byte[]{3},Files.readAllBytes(remote.resolve("key.bin")));transport.execute(1,1,Map.of("operation","MOVE","sourcePath","/key.bin","targetPath","/renamed.bin"),null,"unused");assertFalse(Files.exists(remote.resolve("key.bin")));assertArrayEquals(new byte[]{3},Files.readAllBytes(remote.resolve("renamed.bin")));assertThrows(IllegalArgumentException.class,()->transport.execute(1,1,Map.of("operation","MOVE","sourcePath","/renamed.bin","targetPath","/file.bin"),null,"unused"));assertTrue(Files.exists(remote.resolve("renamed.bin")));config.put("privateKey","invalid-private-key-secret");var invalid=transport.test(1);assertEquals("SSH_KEY_INVALID",invalid.get("errorCode"));assertFalse(invalid.toString().contains("invalid-private-key-secret"));}finally{target.stop(true);}}
}

